  "codebook": {
    "definition": "Credit-claiming is defined as a senator acting to generate the belief among constituents, local actors, or other target groups that they are personally or jointly responsible for causing a desirable government action or benefit to occur.",
    "clarification": "To classify as credit-claiming, a press release must showcase a completed positive outcome—such as approved federal funding, passed legislation, successfully adopted amendments, or completed executive/regulatory actions—and directly tie the senator's personal efforts (e.g., authoring, co-authoring, securing, requesting, or navigating bureaucracy) to that outcome. The announcement of federal grants flowing directly to the senator's home state or local entities is considered a form of credit-claiming, as it serves to associate the senator with the delivery of material benefits to their constituency.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "The senators explicitly claim that they 'delivered on their promise' and went 'to bat' to secure $12.5 million in federal funding for Butte, Montana."
      },
      {
        "document_id": "1257",
        "explanation": "The senator announces federal funding for the Parma Fire Department and explicitly links it to his personal role in writing and passing the underlying FIRE Act."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming if it merely represents 'position-taking' or 'advertising.' This includes introducing a new bill that has not passed, expressing support or opposition to a policy, urging the administration or other actors to take action, testifying at hearings, or commemorating historic events or deceased individuals without claiming responsibility for a tangible policy or material benefit.",
    "negative_examples": [
      {
        "document_id": "57",
        "explanation": "The senator is only introducing a bill and detailing its provisions, which is position-taking as the legislation has not yet passed."
      },
      {
        "document_id": "918",
        "explanation": "The senator is announcing an upcoming town meeting, which is standard constituency advertising and contains no claims of policy accomplishments."
      }
    ]
  }
}
